import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type DataSyncAnimationProps = Record<string, any>;

const DataSyncAnimation: React.FC<DataSyncAnimationProps> = ({
  backgroundColorStart = "#FFF6EA",
  backgroundColorEnd = "#F78A1D",
  transparentBackground = false,
  textColor = "#4A3320",
  highlightColor = "#EFA11A",
  ringBaseColor = "rgba(244, 162, 97, 0.5)",
  durationInSeconds = 10,
  textLine1 = "sync your",
  highlight1 = "data",
  textLine2 = "across all",
  highlight2 = "platforms",
  topAppImage = "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/React-icon.svg/512px-React-icon.svg.png",
  bottomAppImage = "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Google_%22G%22_logo.svg/1024px-Google_%22G%22_logo.svg.png",
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgStyle = transparentBackground
    ? "transparent"
    : `linear-gradient(to bottom, ${backgroundColorStart}, ${backgroundColorEnd})`;

  // Layout Calculations (Canvas Aware)
  const isPortrait = height > width;
  const s = Math.min(width, height);
  const cx = width / 2;
  const cy = height * 0.55; // Shifted down slightly to balance text
  const radius = s * 0.35;
  const trackWidth = s * 0.085;
  const iconBoxSize = s * 0.22;

  const circumference = 2 * Math.PI * radius;

  // Animations
  const textOpacity = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" });
  const textY = interpolate(frame, [0, 20], [20, 0], { extrapolateRight: "clamp" });

  const iconScale = spring({
    frame: frame - 15,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const ringOpacity = interpolate(frame, [25, 45], [0, 1], { extrapolateRight: "clamp" });

  // Continuous rotation for the "data" packets
  const spinRotation = interpolate(frame, [0, fps * durationInSeconds], [0, 360]);

  // Data packet segments sizing (relative to circumference)
  const yellowLen = circumference * 0.28;
  const magentaLen = circumference * 0.03;
  const whiteLen = circumference * 0.02;
  const orangeLen = circumference * 0.03;
  
  const gap = circumference * 0.01;

  const yellowOffset = 0;
  const magentaOffset = -(yellowLen + gap);
  const whiteOffset = magentaOffset - (magentaLen + gap);
  const orangeOffset = whiteOffset - (whiteLen + gap);

  return (
    <AbsoluteFill style={{ background: bgStyle, fontFamily: "Inter, sans-serif" }}>
      
      {/* Text Area */}
      <div
        style={{
          position: "absolute",
          top: isPortrait ? height * 0.12 : height * 0.05,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          opacity: textOpacity,
          transform: `translateY(${textY}px)`,
          transition: "none",
        }}
      >
        <div style={{
          fontSize: s * 0.08,
          fontWeight: 600,
          color: textColor,
          letterSpacing: "-0.03em",
          lineHeight: 1.1,
          textAlign: "center"
        }}>
          {textLine1} <span style={{ color: highlightColor }}>{highlight1}</span>
        </div>
        <div style={{
          fontSize: s * 0.08,
          fontWeight: 600,
          color: textColor,
          letterSpacing: "-0.03em",
          lineHeight: 1.1,
          textAlign: "center"
        }}>
          {textLine2} <span style={{ color: highlightColor }}>{highlight2}</span>
        </div>
      </div>

      {/* Main Graphic Area */}
      <AbsoluteFill style={{ transition: "none" }}>
        {/* Ring SVG Layer */}
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", top: 0, left: 0, opacity: ringOpacity, transition: "none" }}
        >
          {/* Base Track */}
          <circle
            cx={cx}
            cy={cy}
            r={radius}
            fill="none"
            stroke={ringBaseColor}
            strokeWidth={trackWidth}
          />

          {/* Rotating Data Packets */}
          <g style={{ transform: `rotate(${spinRotation}deg)`, transformOrigin: `${cx}px ${cy}px`, transition: "none" }}>
            {/* Yellow Block */}
            <circle
              cx={cx}
              cy={cy}
              r={radius}
              fill="none"
              stroke="#FDE000"
              strokeWidth={trackWidth * 1.05}
              strokeDasharray={`${yellowLen} ${circumference}`}
              strokeDashoffset={yellowOffset}
              strokeLinecap="butt"
            />
            {/* Magenta Block */}
            <circle
              cx={cx}
              cy={cy}
              r={radius}
              fill="none"
              stroke="#E816A5"
              strokeWidth={trackWidth * 1.05}
              strokeDasharray={`${magentaLen} ${circumference}`}
              strokeDashoffset={magentaOffset}
              strokeLinecap="butt"
            />
            {/* White Block */}
            <circle
              cx={cx}
              cy={cy}
              r={radius}
              fill="none"
              stroke="#FFFFFF"
              strokeWidth={trackWidth * 1.05}
              strokeDasharray={`${whiteLen} ${circumference}`}
              strokeDashoffset={whiteOffset}
              strokeLinecap="butt"
            />
            {/* Orange Block */}
            <circle
              cx={cx}
              cy={cy}
              r={radius}
              fill="none"
              stroke="#FF8A00"
              strokeWidth={trackWidth * 1.05}
              strokeDasharray={`${orangeLen} ${circumference}`}
              strokeDashoffset={orangeOffset}
              strokeLinecap="butt"
            />
          </g>
        </svg>

        {/* Top Icon (Custom Image) */}
        <div
          style={{
            position: "absolute",
            left: cx - iconBoxSize / 2,
            top: cy - radius - iconBoxSize / 2,
            width: iconBoxSize,
            height: iconBoxSize,
            backgroundColor: "#FFFFFF",
            borderRadius: iconBoxSize * 0.2,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
            transform: `scale(${iconScale})`,
            transition: "none",
          }}
        >
          <img 
            src={topAppImage} 
            alt="Top App Logo" 
            style={{ width: iconBoxSize * 0.6, height: iconBoxSize * 0.6, objectFit: "contain" }} 
          />
        </div>

        {/* Bottom Icon (Custom Image) */}
        <div
          style={{
            position: "absolute",
            left: cx - iconBoxSize / 2,
            top: cy + radius - iconBoxSize / 2,
            width: iconBoxSize,
            height: iconBoxSize,
            backgroundColor: "#FFFFFF",
            borderRadius: iconBoxSize * 0.2,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
            transform: `scale(${iconScale})`,
            transition: "none",
          }}
        >
          <img 
            src={bottomAppImage} 
            alt="Bottom App Logo" 
            style={{ width: iconBoxSize * 0.65, height: iconBoxSize * 0.65, objectFit: "contain" }} 
          />
        </div>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default DataSyncAnimation;